using System.Collections;using Alterverse.Visuals;using UnityEngine;
namespace Alterverse.Combat
{
public sealed class LaneWaveSpawner:MonoBehaviour
{
[SerializeField]private float firstWaveDelay=4,waveInterval=25,unitSpacing=1.1f;[SerializeField]private int unitsPerWave=3;private static readonly float[] LaneZ={16,-16};private IEnumerator Start(){yield return WaitGameSeconds(firstWaveDelay);while(true){SpawnAllLanes();yield return WaitGameSeconds(waveInterval);}}private static IEnumerator WaitGameSeconds(float seconds){float elapsed=0f;while(elapsed<seconds){if(Time.timeScale>0f)elapsed+=Time.deltaTime;yield return null;}}private void SpawnAllLanes(){if(Time.timeScale<=0f)return;foreach(float laneZ in LaneZ){SpawnWave(0,laneZ);SpawnWave(1,laneZ);}}
private void SpawnWave(int team,float laneZ){float startX=team==0?-30:30,destinationX=team==0?31:-31,direction=team==0?-1:1;for(int i=0;i<unitsPerWave;i++){Vector3 spawn=new(startX+direction*i*unitSpacing,.55f,laneZ);CreateMinion(team,spawn,new Vector3(destinationX,.55f,laneZ),i);}}
private static void CreateMinion(int team,Vector3 spawn,Vector3 destination,int index){Color energy=team==0?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy,dark=team==0?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;GameObject minion=GameObject.CreatePrimitive(PrimitiveType.Capsule);minion.name=team==0?$"DF_ZeroMinion_{index}":$"DF_LumenMinion_{index}";minion.transform.position=spawn;GameObject world=GameObject.Find("DF_MatchWorld");if(world!=null)minion.transform.SetParent(world.transform,true);minion.transform.localScale=new Vector3(.5f,.5f,.5f);Renderer renderer=minion.GetComponent<Renderer>();if(renderer!=null)renderer.material.color=dark;Health health=minion.AddComponent<Health>();health.Configure(70,true);minion.AddComponent<LaneMinion>().Initialize(team,destination);CreatePart(minion.transform,"DF_Visor",PrimitiveType.Cube,new Vector3(0,.42f,.42f),new Vector3(.62f,.12f,.10f),energy);CreatePart(minion.transform,"DF_Shoulder",PrimitiveType.Cube,new Vector3(0,.12f,0),new Vector3(.92f,.14f,.5f),energy);Object.Destroy(minion,75);}
private static void CreatePart(Transform parent,string name,PrimitiveType type,Vector3 pos,Vector3 scale,Color color){GameObject p=GameObject.CreatePrimitive(type);p.name=name;p.transform.SetParent(parent,false);p.transform.localPosition=pos;p.transform.localScale=scale;Collider c=p.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=p.GetComponent<Renderer>();if(r!=null)r.material.color=color;}
}
}
